//! Rust chat index replays the TypeScript `searchMessagesInChat` vectors
//! (web_search_chats_ts_vectors.json, generated by chatSearchVectors.test.ts),
//! plus ingest ordering, budget eviction and wire decoding.
use crate::web_search::utf16_len;
use crate::web_search_chats::*;
use serde_json::{json, Value};

fn vectors() -> Value {
    serde_json::from_str(include_str!("web_search_chats_ts_vectors.json")).unwrap()
}

fn entry(message_id: &str, content: &str, created_at: f64, meta: Option<EntryMeta>) -> IngestEntry {
    IngestEntry {
        message_id: message_id.into(),
        content: content.into(),
        created_at,
        meta,
    }
}

fn embed(id: &str, title: &str) -> EntryMeta {
    EntryMeta {
        source_label: Some("Doc".into()),
        embed_id: Some(id.into()),
        embed_type: Some("docs-doc".into()),
        title: Some(title.into()),
        ..EntryMeta::default()
    }
}

#[test]
fn chat_search_equals_typescript() {
    let vectors = vectors();
    let mut index = ChatSearchIndex::default();
    let mut handles = std::collections::HashMap::new();
    for (n, (name, entries)) in vectors["chats"].as_object().unwrap().iter().enumerate() {
        let handle = n as u32 + 1;
        handles.insert(name.clone(), handle);
        let ingest = entries
            .as_array()
            .unwrap()
            .iter()
            .enumerate()
            .map(|(at, item)| {
                let meta = item["embedId"]
                    .as_str()
                    .map(|id| embed(id, item["embedTitle"].as_str().unwrap_or("")));
                // The generator stamps createdAt = 1000 - index (newest first).
                entry(
                    item["messageId"].as_str().unwrap(),
                    item["content"].as_str().unwrap(),
                    1000.0 - at as f64,
                    meta,
                )
            })
            .collect();
        assert!(index.ingest_chat(handle, ingest).is_empty());
    }
    for case in vectors["cases"].as_array().unwrap() {
        let chat = case["chat"].as_str().unwrap();
        let query_text = case["query"].as_str().unwrap();
        let query = LoweredQuery::new(query_text);
        let hits = index
            .chat_hits(
                handles[chat],
                &query,
                case["includeEmbeds"].as_bool().unwrap(),
            )
            .unwrap();
        let actual = json!({
            "snippets": hits.snippets.iter().map(|hit| json!({
                "messageId": hit.entry.message_id,
                "embedId": hit.entry.meta.and_then(|meta| meta.embed_id.clone()),
                "snippetUnits": hit.slice.units(hit.entry.text),
                "matchStart": hit.slice.match_start,
                "matchLength": utf16_len(query_text),
            })).collect::<Vec<_>>(),
            "embeds": hits.embeds.iter().map(|view| json!({
                "embedId": view.meta.and_then(|meta| meta.embed_id.clone()),
                "messageId": view.message_id,
            })).collect::<Vec<_>>(),
        });
        assert_eq!(actual, case["expected"], "{case}");
    }
}

#[test]
fn ingest_orders_newest_first_with_message_text_before_embeds() {
    let mut index = ChatSearchIndex::default();
    index.ingest_chat(
        3,
        vec![
            entry("old", "needle old", 1.0, None),
            entry("new", "needle embed", 5.0, Some(embed("e", "T"))),
            entry("new", "needle text", 5.0, None),
        ],
    );
    let query = LoweredQuery::new("needle");
    let hits = index.chat_hits(3, &query, false).unwrap();
    let texts: Vec<&str> = hits.snippets.iter().map(|hit| hit.entry.text).collect();
    assert_eq!(texts, vec!["needle text", "needle embed", "needle old"]);
    assert!(index.chat_hits(4, &query, false).is_none());
}

#[test]
fn ascii_entries_match_case_insensitively_without_a_lowercase_copy() {
    let mut index = ChatSearchIndex::default();
    index.ingest_chat(1, vec![entry("m", "Say PANDAS twice: pandas", 1.0, None)]);
    let hits = index
        .chat_hits(1, &LoweredQuery::new("Pandas"), false)
        .unwrap();
    assert_eq!(hits.snippets.len(), 1);
    assert_eq!(
        String::from_utf16(&hits.snippets[0].slice.units(hits.snippets[0].entry.text)).unwrap(),
        "Say PANDAS twice: pandas"
    );
    assert_eq!(hits.snippets[0].slice.match_start, 4);
    assert!(index
        .chat_hits(1, &LoweredQuery::new("ß"), false)
        .unwrap()
        .snippets
        .is_empty());
    // Kelvin sign lowercases to ASCII "k", as in JS.
    index.ingest_chat(2, vec![entry("m", "ok", 1.0, None)]);
    assert_eq!(
        index
            .chat_hits(2, &LoweredQuery::new("\u{212A}"), false)
            .unwrap()
            .snippets
            .len(),
        1
    );
}

#[test]
fn budget_evicts_least_recently_used_chats_and_reports_them() {
    let mut index = ChatSearchIndex::with_limits(usize::MAX, 2);
    assert!(index
        .ingest_chat(1, vec![entry("a", "one", 1.0, None)])
        .is_empty());
    assert!(index
        .ingest_chat(2, vec![entry("b", "two", 1.0, None)])
        .is_empty());
    index.touch(&[1]);
    assert_eq!(
        index.ingest_chat(3, vec![entry("c", "three", 1.0, None)]),
        vec![2]
    );
    assert_eq!(index.chat_count(), 2);
    let mut tiny = ChatSearchIndex::with_limits(10, 10);
    assert_eq!(
        tiny.ingest_chat(
            7,
            vec![entry("a", "far too large for ten bytes", 1.0, None)]
        ),
        vec![7]
    );
    assert_eq!(tiny.retained_bytes(), 0);
    index.remove_chat(3);
    index.clear();
    assert_eq!((index.chat_count(), index.retained_bytes()), (0, 0));
}

#[test]
fn decode_ingest_refuses_mismatched_columns() {
    let ids = || vec!["m".to_string()];
    let texts = || vec!["t".to_string()];
    let decoded = decode_ingest(
        ids(),
        texts(),
        &[2.0],
        &[0],
        &[0b1001],
        vec!["Doc".into(), "Title".into()],
    )
    .unwrap();
    let meta = decoded[0].meta.as_ref().unwrap();
    assert_eq!(
        (
            meta.source_label.as_deref(),
            meta.title.as_deref(),
            meta.embed_id.as_deref()
        ),
        (Some("Doc"), Some("Title"), None)
    );
    let bad = [
        decode_ingest(ids(), vec![], &[2.0], &[], &[], vec![]),
        decode_ingest(ids(), texts(), &[2.0], &[1], &[1], vec!["x".into()]),
        decode_ingest(ids(), texts(), &[2.0], &[0], &[1], vec![]),
        decode_ingest(
            ids(),
            texts(),
            &[2.0],
            &[0],
            &[1],
            vec!["x".into(), "y".into()],
        ),
        decode_ingest(ids(), texts(), &[2.0], &[0], &[1 << 9], vec![]),
        decode_ingest(ids(), texts(), &[2.0], &[0, 0], &[0, 0], vec![]),
    ];
    for result in bad {
        assert_eq!(result.unwrap_err().code(), "protocol");
    }
}
